import sqlite3

c = sqlite3.connect('analytics.db')
steps = ['install', 'tutorial_complete', 'first_match', 'purchase']

# Independent check: per platform, per step, count players whose first valid
# occurrence of the step is >= first valid occurrence of previous step.
sql = """
WITH firsts AS (
  SELECT e.user_id, e.name, MIN(e.ts) AS ts
  FROM events e JOIN users u ON u.user_id = e.user_id
  WHERE u.is_test = 0 AND e.name IN ('install','tutorial_complete','first_match','purchase')
  GROUP BY e.user_id, e.name
)
SELECT u.platform,
  SUM(CASE WHEN f1.ts IS NOT NULL THEN 1 ELSE 0 END),
  SUM(CASE WHEN f2.ts IS NOT NULL AND f1.ts IS NOT NULL AND f2.ts >= f1.ts THEN 1 ELSE 0 END),
  SUM(CASE WHEN f3.ts IS NOT NULL AND f2.ts IS NOT NULL AND f3.ts >= f2.ts THEN 1 ELSE 0 END),
  SUM(CASE WHEN f4.ts IS NOT NULL AND f3.ts IS NOT NULL AND f4.ts >= f3.ts THEN 1 ELSE 0 END)
FROM users u
LEFT JOIN firsts f1 ON f1.user_id = u.user_id AND f1.name = 'install'
LEFT JOIN firsts f2 ON f2.user_id = u.user_id AND f2.name = 'tutorial_complete'
LEFT JOIN firsts f3 ON f3.user_id = u.user_id AND f3.name = 'first_match'
LEFT JOIN firsts f4 ON f4.user_id = u.user_id AND f4.name = 'purchase'
WHERE u.is_test = 0
GROUP BY u.platform
"""
for row in c.execute(sql):
    print(row)

# sanity: event names present
print(c.execute("SELECT DISTINCT name FROM events").fetchall())
print(c.execute("SELECT COUNT(*) FROM users WHERE is_test=1").fetchone())

--- funnel.py ---
import sqlite3, json

c = sqlite3.connect('analytics.db')
steps = ['install', 'tutorial_complete', 'first_match', 'purchase']

# valid players: known (in users) and not test
players = {uid: plat for uid, plat, is_test in c.execute("SELECT user_id, platform, is_test FROM users") if not is_test}

# first occurrence of each event per player, but a step counts only at/after the previous step
first = {}  # (uid, step) -> ts
for uid, name, ts in c.execute("SELECT user_id, name, ts FROM events"):
    if uid not in players or name not in steps:
        continue
    k = (uid, name)
    if k not in first or ts < first[k]:
        k and first.__setitem__(k, ts)

funnel = {}
biggest = {}
for plat in sorted({p for p in players.values()}):
    pids = [u for u, p in players.items() if p == plat]
    counts = {}
    for i, s in enumerate(steps):
        prev = steps[i-1] if i > 0 else None
        n = 0
        for u in pids:
            t = first.get((u, s))
            if t is None:
                continue
            if prev is None:
                n += 1
            else:
                tp = first.get((u, prev))
                if tp is not None and t >= tp:
                    n += 1
        counts[s] = n
    funnel[plat] = counts
    # conversions
    convs = {}
    for i, s in enumerate(steps):
        if i == 0:
            convs[s] = None
        else:
            prev = steps[i-1]
            convs[s] = (counts[s] / counts[prev]) if counts[prev] else None
    valid = {s: v for s, v in convs.items() if v is not None}
    biggest[plat] = min(valid, key=valid.get)

out = {"funnel": funnel, "biggest_drop": biggest}
with open('result.json', 'w') as f:
    json.dump(out, f, indent=2)
print(json.dumps(out, indent=2))

